// Embeds the YAML files in sites/ into the core package, so the engine can
// load the built-in sites in Node and in the browser. Run by npm run build
// and npm test. The generated file is committed; a test checks it is current.

import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const read = (dir) =>
  readdirSync(join(root, dir))
    .filter((f) => f.endsWith(".yaml"))
    .sort()
    .map((f) => {
      const text = readFileSync(join(root, dir, f), "utf8");
      const id = text.match(/^id:\s*([a-z0-9-]+)\s*$/m)?.[1];
      if (!id) throw new Error(`${dir}/${f}: no "id:" line`);
      return [id, text];
    });

export function generate() {
  const sites = Object.fromEntries(read("sites"));
  const templates = Object.fromEntries(read("sites/templates"));
  return `// Generated by scripts/embed-sites.mjs from sites/*.yaml. Do not edit by hand.

export const BUILTIN_SITE_FILES: Record<string, string> = ${JSON.stringify(sites, null, 2)};

export const SITE_TEMPLATES: Record<string, string> = ${JSON.stringify(templates, null, 2)};
`;
}

const out = join(root, "packages/core/src/sites/builtin.generated.ts");
if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  writeFileSync(out, generate());
  console.log(`wrote ${out.replace(root + "/", "")}`);
}
